import { expect, test } from 'bun:test';
import { fitsWindow, moveUp, screenRequiresReason } from './logic';
import type { Stop } from './domain';

const stops: Stop[] = [
  { id: 'a', position: 2, status: 'NEW' },
  { id: 'removed', position: 3, status: 'NEW', removed: true },
  { id: 'b', position: 9, status: 'POSTPONED', startedOn: '2026-01-01' },
];

test('moves by active rank and handles boundaries', () => {
  expect(moveUp(stops, 1)).toEqual({ id: 'b', position: 1 });
  expect(moveUp(stops, 0)).toBeUndefined();
  expect(moveUp(stops, 2)).toBeUndefined();
});

test('reason follows the domain predicate', () => {
  expect(screenRequiresReason(stops[1])).toBe(false);
  expect(screenRequiresReason(stops[2])).toBe(true);
  expect(screenRequiresReason({ ...stops[2], status: 'DONE' })).toBe(false);
  expect(screenRequiresReason({ ...stops[2], startedOn: undefined, status: 'IN_PROGRESS' })).toBe(false);
});

test('slot uses inclusive notification and exclusive next upcoming eligible appointment', () => {
  const appointments = [{ at: 5, status: 'PLANNED' }, { at: 12, status: 'HELD' }, { at: 13, status: 'CANCELLED' }, { at: 20, status: 'PLANNED' }];
  expect(fitsWindow(10, { sentAt: 10 }, appointments, 10)).toBe(true);
  expect(fitsWindow(9, { sentAt: 10 }, appointments, 10)).toBe(false);
  expect(fitsWindow(20, { sentAt: 10 }, appointments, 10)).toBe(false);
  expect(fitsWindow(15, { sentAt: 10 }, appointments.slice(0, 3), 10)).toBe(false);
});
EOF
